import{z as s,x as l,o as E,c as A,q as t,j as n,D as e,d as i,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"数字与二元","description":"","frontmatter":{"title":"数字与二元","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/digital-options.md","filePath":"quant/digital-options.md","lastUpdated":1791063341000}'),d={name:"quant/digital-options.md"};function p(_,a,m,D,h,u){const r=l("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="数字与二元" tabindex="-1">数字与二元 <a class="header-anchor" href="#数字与二元" aria-label="Permalink to &quot;数字与二元&quot;">​</a></h1><div class="epigraph"><p>现金或无的二元是执行价处的 Dirac；它的价格是风险中性概率的贴现，希腊值在 K 附近像密度而不是像累积分布。</p><footer>—— Reiner and Rubinstein, Unscrambling the Binary Code, Risk, 1991</footer></div><p><a href="/quant/lookback-options">上一课</a>的支付随极值连续变化。本课把支付收成<strong>示性函数</strong>：到期 \\(S_T\\gt K\\) 则付一笔固定现金（现金或无），或付一单位标的（资产或无）。缺口是：香草是积分，数字是密度；对冲与报价惯例都因此断裂。后课障碍解析解会把「触碰」再写进路径；这里先把欧式二元与香草的平价写清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>现金或无看涨价格是 \\(e^{-rT}N_c\\,\\mathbb{Q}(S_T\\gt K)\\)（\\(N_c\\) 为现金名义）。在 <a href="/quant/bsm">BSM</a> 下这就是贴现的 \\(N(d_2)\\)，不是 \\(N(d_1)\\)。资产或无是 \\(e^{-qT}S_0 N(d_1)\\)。香草看涨 $= $ 资产或无 \\(-K\\times\\) 现金或无。这组平价在模型无关的层面也近似成立（欧式、同一 \\(K\\)）。问题不是再推 \\(d_1,d_2\\)，而是：<strong>数字的 Delta 是密度，在 \\(K\\) 附近爆炸，离散对冲会系统性漏掉针状 Gamma。</strong></p><p><span class="marginnote">数字实例：一张名义 1 元、现价 0.42 元的现金或无看涨，在利率近零时就在直白地告诉你：市场认为到期收在 \\(K\\) 之上的概率约 42%。数字因此是所有期权里最接近「直接买卖概率」的工具——它没有杠杆放大收益的部分，只有概率本身。</span></p><p>二元在结构票据、障碍的「返现」、以及外汇触碰里大量出现。卖方若按香草簿的 Vega 桶去套，会发现数字对偏斜的敏感是香草对 \\(K\\) 求导——也就是对微笑的局部斜率，而不是对 ATM 水平。</p><h3 id="数字是香草对执行价的导数" tabindex="-1">数字是香草对执行价的导数 <a class="header-anchor" href="#数字是香草对执行价的导数" aria-label="Permalink to &quot;数字是香草对执行价的导数&quot;">​</a></h3><p>在利率确定等正则条件下，</p> \\[\\frac{\\partial C}{\\partial K}=-e^{-rT}\\mathbb{Q}(S_T\\gt K) \\]<p>（看涨、现金或无名义为 1）。因此市场若给出密的香草报价，数字价格可以由相邻执行价的价差逼近，不必另校准一个「数字隐波」。实现时买卖价差与离散 \\(K\\) 网格会让这个导数很吵，这是报价问题，不是模型没选对。</p>',11)),(E(),n(o,null,{default:e(()=>[B(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20VAN%5B%22%E9%A6%99%E8%8D%89%E7%9C%8B%E6%B6%A8%22%5D%0A%20%20%20%20VP%5B%22%E6%94%AF%E4%BB%98%EF%BC%9A%E6%96%9C%E5%9D%A1%EF%BC%8CK%20%E4%BB%A5%E4%B8%8A%E6%AF%8F%E6%B6%A8%201%20%E5%85%83%E5%A4%9A%E5%BE%97%201%20%E5%85%83%22%5D%20--%3E%20VD%5B%22Delta%EF%BC%9A%E4%BB%8E%200%20%E5%B9%B3%E6%BB%91%E7%88%AC%E5%88%B0%201%22%5D%0A%20%20%20%20VD%20--%3E%20VG%5B%22Gamma%EF%BC%9A%E6%B8%A9%E5%92%8C%EF%BC%8C%E7%A6%BB%E5%88%B0%E6%9C%9F%E5%8F%98%E5%B0%96%E4%BD%86%E6%9C%89%E9%99%90%22%5D%0A%20%20end%0A%20%20subgraph%20DIG%5B%22%E7%8E%B0%E9%87%91%E6%88%96%E6%97%A0%E6%95%B0%E5%AD%97%22%5D%0A%20%20%20%20DP%5B%22%E6%94%AF%E4%BB%98%EF%BC%9A%E6%82%AC%E5%B4%96%EF%BC%8CK%20%E5%8F%B3%E4%BE%A7%E6%81%92%E4%B8%BA%E5%90%8D%E4%B9%89%22%5D%20--%3E%20DD%5B%22Delta%EF%BC%9AK%20%E5%A4%84%E5%AF%86%E5%BA%A6%E5%B3%B0%E5%80%BC%EF%BC%8C%E5%8F%AF%E8%BF%9C%E8%B6%85%201%22%5D%0A%20%20%20%20DD%20--%3E%20DG%5B%22Gamma%EF%BC%9A%E6%AD%A3%E8%B4%9F%E9%92%88%E7%8A%B6%E5%AF%B9%EF%BC%8C%E8%B4%B4%20K%20%E6%97%B6%E7%88%86%E7%82%B8%22%5D%0A%20%20end%0A%20%20VAN%20--%3E%7C%22%E5%AF%B9%20K%20%E6%B1%82%E5%AF%BC%22%7C%20DIG%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">常见误区：初学者容易以为数字的 Delta 和香草一样封顶在 1、可以用同样的节奏再平衡。实际上临近到期、标的贴着 \\(K\\) 时，结果近乎纯抛硬币——半个 tick 的移动就让价值在 0 与 1 之间翻面，这一刻的对冲比例理论上没有上界。裸卖数字在到期日的最后一小时，不是「小一点的香草风险」，是另一物种。</span></p><p><span class="marginnote">二元不等于障碍。欧式二元只看 \\(S_T\\) 与 \\(K\\)；一触即付（one-touch）看路径是否触及 \\(H\\)，对象在后课障碍与 FX 触碰。不要把 \\(N(d_2)\\) 当成触碰概率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>欧式现金或无：用香草蝶式/价差的极限，或在已校准的 <a href="/quant/dupire">Dupire</a> 密度上积分示性。资产或无：用远期测度下的概率。对冲：理论上用紧邻的看涨价差复制数字，宽度 \\(\\Delta K\\) 越小复制越真、Gamma 越尖。实务用有限宽度价差，接受基差，避免在 \\(K\\) 上挂无限大的裸数字 Gamma。</p><p>美式二元、日内触碰、以及「到期前任意时刻」都不是本课的 \\(N(d_2)\\)。那些要路径，接到 <a href="/quant/barrier-analytics">障碍解析解</a>。有跳过程时 \\(S_T\\) 密度在 \\(K\\) 处不必连续，数字价格对跳强度一阶敏感，局部波动未必够。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>香草把密度积分成平滑的价值；数字把密度本身当成支付的核。于是 Vega、Vanna 都通过密度对参数的导数进来，而不是通过累积分布。微笑上，数字报价常被说成「数字隐波」或「风险反转的斜率」：本质是 Breeden–Litzenberger 密度在 \\(K\\) 的一块。把数字当「便宜的香草」卖，是在卖针状对冲误差，不是在卖波动水平。</p><p><span class="marginnote">直觉类比：香草像爬坡——山顶之后再爬，赚的每一米都算数；数字像悬崖边的闸门——只问你最终站在线左边还是右边，越线一厘米和越线一公里拿到完全相同的钱。所以对香草，路径途中的距离有意义；对数字，只有终点那一刻的位置有意义。</span></p>',8)),(E(),n(o,null,{default:e(()=>[B(r,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20Van%5B%22%E6%AC%A7%E5%BC%8F%E9%A6%99%E8%8D%89%20C(K)%22%5D%20--%3E%20Der%5B%22%E5%AF%B9%20K%20%E6%B1%82%E5%AF%BC%22%5D%0A%20%20Der%20--%3E%20Dig%5B%22%E7%8E%B0%E9%87%91%E6%88%96%E6%97%A0%20%E8%B4%B4%E7%8E%B0%E9%A3%8E%E9%99%A9%E4%B8%AD%E6%80%A7%E6%A6%82%E7%8E%87%22%5D%0A%20%20Dig%20--%3E%20Spd%5B%22%E6%9C%89%E9%99%90%E5%AE%BD%E5%BA%A6%E7%9C%8B%E6%B6%A8%E4%BB%B7%E5%B7%AE%E5%A4%8D%E5%88%B6%22%5D%0A%20%20Spd%20--%3E%20Hedge%5B%22%E6%8E%A5%E5%8F%97%E5%9F%BA%E5%B7%AE%20%E9%81%BF%E5%85%8D%E8%A3%B8%E6%95%B0%E5%AD%97%20Gamma%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>BSM 的 \\(N(d_2)\\) 只在对数正态下等于数字价格除以贴现名义。有微笑时必须用曲面密度。<a href="/quant/discrete-hedge-error">离散对冲误差</a> 对数字特别狠：对冲间隔内只要 \\(S\\) 扫过 \\(K\\)，复制组合会整段错位。涨跌停、最小跳动使「恰好在 \\(K\\)」的事件有正原子质量，连续密度公式失效。</p><p>本课不讨论如何把二元嵌进赌大小的零售产品去规避适当性。对象是支付定义、平价与对冲结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欧式现金或无是贴现的 \\(\\mathbb{Q}(S_T\\gt K)\\)，对应香草对 \\(K\\) 的导数，不是 \\(N(d_1)\\)。</li><li>复制用有限宽度价差；裸数字的 Gamma 是针，离散对冲会漏。</li><li>一触即付是路径事件，不要用到期数字公式去冒充。</li><li>出处：Reiner and Rubinstein, <em>Risk</em>, 1991；密度与香草条带见 Breeden and Litzenberger, <em>Journal of Business</em>, 1978。</li></ul>',5))])}const g=s(d,[["render",p]]);export{c as __pageData,g as default};
